import{_ as t,o,c as r,a3 as a}from"./chunks/framework.BrO6lPIi.js";const u=JSON.parse('{"title":"流式会话与定稿引擎","description":"语音链路分两段：**流式（草稿）**与**定稿**。","frontmatter":{"title":"流式会话与定稿引擎","description":"语音链路分两段：**流式（草稿）**与**定稿**。"},"headers":[],"relativePath":"语音输入/流式会话与定稿引擎/index.md","filePath":"语音输入/流式会话与定稿引擎/index.md","lastUpdated":null}'),d={name:"语音输入/流式会话与定稿引擎/index.md"};function c(i,e,l,s,n,h){return o(),r("div",null,[...e[0]||(e[0]=[a(`<h1 id="流式会话与定稿引擎" tabindex="-1">流式会话与定稿引擎 <a class="header-anchor" href="#流式会话与定稿引擎" aria-label="Permalink to &quot;流式会话与定稿引擎&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/asr/session.js" target="_blank" rel="noreferrer">agent/src/asr/session.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/asr/offline-pool.js" target="_blank" rel="noreferrer">agent/src/asr/offline-pool.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/asr/offline-worker.js" target="_blank" rel="noreferrer">agent/src/asr/offline-worker.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/asr/engine.js" target="_blank" rel="noreferrer">agent/src/asr/engine.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/asr/transcribe.js" target="_blank" rel="noreferrer">agent/src/asr/transcribe.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/asr/config.js" target="_blank" rel="noreferrer">agent/src/asr/config.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js" target="_blank" rel="noreferrer">agent/src/server.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/voice-input.js" target="_blank" rel="noreferrer">src/side_panel/voice-input.js</a></li></ul></details><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>语音链路分两段：<strong>流式（草稿）<strong>与</strong>定稿</strong>。流式让用户边说边看到文字，定稿在松手后用整段音频重转一遍拿到更高精度结果。两段用的不是同一个模型：<code>online</code> 包负责低延迟草稿，<code>offline</code> 包负责终稿。</p><p>本文说明这条链路上最容易被忽视的三件事：WebSocket 的鉴权与心跳、会话资源的收敛路径、以及为什么 offline 推理必须离开主线程。</p><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#通道建立">通道建立</a></li><li><a href="#帧协议">帧协议</a></li><li><a href="#会话生命周期与资源回收">会话生命周期与资源回收</a></li><li><a href="#定稿worker-线程池">定稿：worker 线程池</a></li><li><a href="#降级与保护">降级与保护</a></li><li><a href="#客户端配合">客户端配合</a></li><li><a href="#结论">结论</a></li></ol><h2 id="通道建立" tabindex="-1">通道建立 <a class="header-anchor" href="#通道建立" aria-label="Permalink to &quot;通道建立&quot;">​</a></h2><p>升级请求由 <code>server.on(&#39;upgrade&#39;)</code> 统一处理，<code>/ws/asr/:sessionId</code> 与 <code>/ws/exec</code> 走同一套鉴权：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /ws/asr/&lt;sessionId&gt;  (Upgrade: websocket)</span></span>
<span class="line"><span>Authorization: Bearer &lt;token&gt;      ← 优先</span></span>
<span class="line"><span>   或 ?token=&lt;token&gt;               ← 回退（浏览器 WebSocket API 无法自定义 Header）</span></span></code></pre></div><p>三道关卡依次是：鉴权失败 → <code>HTTP/1.1 403</code>；依赖不可用 → <code>503 Service Unavailable</code>（客户端据此引导用户去安装）；通过后 <code>handleUpgrade</code>。</p><p>通道建立后每 30 秒 ping 一次，两拍未回 pong 视为半开连接，直接 <code>terminate</code>，走正常断开收敛路径。query token 可能被代理日志或 Referer 记录，因此任何日志都不写入 token 内容。</p><h2 id="帧协议" tabindex="-1">帧协议 <a class="header-anchor" href="#帧协议" aria-label="Permalink to &quot;帧协议&quot;">​</a></h2><p>上行：</p><table tabindex="0"><thead><tr><th>帧</th><th>内容</th></tr></thead><tbody><tr><td>二进制帧</td><td>PCM16LE / 单声道 / 16kHz，每帧约 100ms；单帧上限 320KB（10 秒），超过视为异常客户端</td></tr><tr><td><code>{&quot;type&quot;:&quot;start&quot;,&quot;language&quot;:&quot;auto&quot;}</code></td><td>开始会话，<code>language</code> 缺省沿用配置</td></tr><tr><td><code>{&quot;type&quot;:&quot;stop&quot;}</code></td><td>停止采集并发起定稿</td></tr><tr><td><code>{&quot;type&quot;:&quot;cancel&quot;}</code></td><td>放弃本次会话，不产生结果</td></tr></tbody></table><p>下行：</p><table tabindex="0"><thead><tr><th>帧</th><th>含义</th></tr></thead><tbody><tr><td><code>{&quot;type&quot;:&quot;ready&quot;,&quot;draft&quot;:bool,&quot;finalize&quot;:bool}</code></td><td>会话就绪；<code>draft=false</code> 表示没有可用的流式模型，只等 stop 定稿</td></tr><tr><td><code>{&quot;type&quot;:&quot;partial&quot;,&quot;text&quot;:&quot;…&quot;}</code></td><td>流式草稿，服务端节流 150ms</td></tr><tr><td><code>{&quot;type&quot;:&quot;endpoint&quot;,&quot;text&quot;:&quot;…&quot;}</code></td><td>检测到句尾，草稿已提交为稳定片段，后续不再回改</td></tr><tr><td><code>{&quot;type&quot;:&quot;final&quot;,&quot;text&quot;:&quot;…&quot;,&quot;fallback&quot;:bool}</code></td><td>定稿；<code>fallback=true</code> 表示退化为流式文本</td></tr><tr><td><code>{&quot;type&quot;:&quot;error&quot;,&quot;code&quot;:&quot;…&quot;,&quot;error&quot;:&quot;…&quot;}</code></td><td><code>busy</code> / <code>model_missing</code> / <code>internal</code> / <code>rss_pressure</code></td></tr></tbody></table><p><code>partial</code> 的节流是刻意的：不节流会把 WebSocket 打满，逐帧刷新肉眼也读不及；150ms 既连贯又不浪费带宽。<code>endpoint</code> 与 <code>partial</code> 的区别在于<strong>可回改性</strong>——稳定片段只追加，不会因为后文修正而整句重排。</p><h2 id="会话生命周期与资源回收" tabindex="-1">会话生命周期与资源回收 <a class="header-anchor" href="#会话生命周期与资源回收" aria-label="Permalink to &quot;会话生命周期与资源回收&quot;">​</a></h2><p>所有路径最终都收敛到 <code>release()</code>：</p><table tabindex="0"><thead><tr><th>触发</th><th>说明</th></tr></thead><tbody><tr><td>连接关闭（未 stop）</td><td>用户关掉侧边栏或网络断开</td></tr><tr><td>空闲 30 秒</td><td><code>SESSION_IDLE_MS</code>，收不到任何帧即释放</td></tr><tr><td>总时长 5 分钟</td><td><code>MAX_RECORDING_MS</code>，超时结束并定稿</td></tr><tr><td>并发超限</td><td><code>MAX_SESSIONS</code> 默认 1，第二个请求直接回 <code>busy</code></td></tr></tbody></table><p><code>release()</code> 归还并发名额与流式资源（识别器状态、累计文本缓冲），这是「不会因为一次异常录音把唯一的会话名额占死」的唯一保证。</p><p><code>stop</code> 的处理值得单独说明：<strong>发起定稿的那一刻就 <code>release()</code></strong>，final 帧等 worker 回来再补发。也就是说定稿期间用户可以立刻开始下一次录音，不必等几百毫秒到数十秒的推理结束。代价是客户端要能接受「会话已结束但结果还没到」，这由下文的兜底定时器覆盖。</p><h2 id="定稿-worker-线程池" tabindex="-1">定稿：worker 线程池 <a class="header-anchor" href="#定稿-worker-线程池" aria-label="Permalink to &quot;定稿：worker 线程池&quot;">​</a></h2><p><code>sherpa-onnx</code> 的 decode 是同步原生调用，耗时从几百毫秒到数十秒。若放在主线程的 WebSocket 回调里，整个 Agent 的事件循环会停摆：<code>/health</code> 探活、cancel 帧、聊天流式响应、工具执行全部排队，用户看到的现象是「点了停止代理像死了一样」。</p><p>因此 offline 推理搬到 <code>worker_threads</code>（<code>offline-pool.js</code> + <code>offline-worker.js</code>），主线程只等消息：</p><table tabindex="0"><thead><tr><th>设计点</th><th>原因</th></tr></thead><tbody><tr><td>单 worker + 串行队列</td><td>本机单用户形态下并发定稿只会抢同一份 CPU 与内存；串行也保证 worker 内那个几百 MB 的 ONNX 会话不会被两次 decode 交错使用</td></tr><tr><td>首个任务才 spawn</td><td>未启用 ASR 的用户零成本</td></tr><tr><td>空闲 <code>idleMs</code> 后 dispose</td><td><code>terminate</code> 把几百 MB 原生内存还给系统</td></tr><tr><td>崩溃 / 超时 → 丢弃 worker</td><td>reject 在途任务，下个任务重新 spawn；默认单任务超时 180 秒</td></tr><tr><td>spawn 失败 → 退回主线程</td><td>宁可卡一下，也不能让语音输入整个不可用</td></tr></tbody></table><p>一个容易误解的点：<code>worker_threads</code> 与主线程<strong>共享同一进程地址空间</strong>，<code>process.memoryUsage().rss</code> 覆盖 worker 内的原生分配。所以把推理搬进 worker 不会让 RSS 保护失准，反而让保护继续有效。</p><h2 id="降级与保护" tabindex="-1">降级与保护 <a class="header-anchor" href="#降级与保护" aria-label="Permalink to &quot;降级与保护&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>行为</th></tr></thead><tbody><tr><td>无 <code>offline</code> 模型</td><td><code>ready.finalize=false</code>，只做流式，stop 时直接用草稿文本</td></tr><tr><td>定稿失败</td><td><code>final</code> 带 <code>fallback=true</code>，用草稿兜底，不向用户抛错</td></tr><tr><td>RSS 超限</td><td>超过 <code>RSS_LIMIT_BYTES</code>（默认 3.5GB）跳过 offline 推理，回 <code>rss_pressure</code> 并退化</td></tr><tr><td>worker 超时</td><td>同上，丢弃 worker 后回退</td></tr></tbody></table><p>降级的判断标准是「用户能否拿到文字」，而不是「是否拿到最好的文字」。任何一次异常都不应该让整段录音白说。</p><h2 id="客户端配合" tabindex="-1">客户端配合 <a class="header-anchor" href="#客户端配合" aria-label="Permalink to &quot;客户端配合&quot;">​</a></h2><p><code>src/side_panel/voice-input.js</code> 承担上行采集与状态机：</p><ul><li>采集优先用 <code>AudioWorklet</code>（<code>voice-capture-worklet.js</code>），<code>addModule</code> 失败时回退 <code>ScriptProcessor</code>。两条路径都要工作，因为不同安装形态下 worklet 文件的相对位置不同。</li><li>优先向 <code>AudioContext</code> 请求 16kHz；拿不到就在回调里做线性插值重采样，保证上送格式恒为 16kHz。</li><li>点开始前再跑一次门控复查。<code>refreshGating()</code> 是异步的，这期间若另一路（快捷键 / 按钮）已经进入 <code>starting</code> 或 <code>recording</code>，不复查就会出现两路并发采集——前一组 <code>AudioContext</code> 与 <code>MediaStream</code> 被后者覆盖且永不释放（麦克风指示灯常亮），两路帧还会同时上送。</li><li>stop 之后起 60 秒兜底定时器：代理端迟迟不回 <code>final</code>（网络挂住、模型加载慢）时用最后一条草稿收尾，不让 UI 卡在转写态。</li><li>太短的录音不发 <code>stop</code>，直接回滚草稿并提示，避免为一个语气词付一次完整推理。</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>这条链路的可靠性来自三处<strong>明确的兜底</strong>：并发名额靠 <code>release()</code> 收敛、推理线程靠队列与超时收敛、结果靠 fallback 收敛。反过来说，任何一处缺失都会表现为「偶发卡死」或「偶发丢字」，且难以复现。新增相关功能时，这三条边界不应被绕过。</p>`,36)])])}const b=t(d,[["render",c]]);export{u as __pageData,b as default};
